    private Symbol token(int type) {

        System.out.println(
            "[" + (yyline + 1) + "-" + (yycolumn + 1) + "] "
            + "token: " + yytext()
        );

        return new Symbol(
            type,
            yyline + 1,
            yycolumn + 1,
            yytext()
        );
    }


